import { Component } from '@angular/core';
import { IonicPage, NavController, NavParams } from 'ionic-angular';
import { ExportItemsPage } from '../export-items/export-items';
import { LocalItemsPage } from '../local-items/local-items';


@IonicPage()
@Component({
  selector: 'page-choose-type',
  templateUrl: 'choose-type.html',
})
export class ChooseTypePage {

  constructor(public navCtrl: NavController, public navParams: NavParams) {
  }

  ionViewDidLoad() {
  }

  openType(type) {
    if (type === 'export') {
      this.navCtrl.push(ExportItemsPage);
    } else {
      this.navCtrl.push(LocalItemsPage);
    }
  }

}



