import { Component, OnInit } from "@angular/core";
import { NavController, AlertController, ToastController, MenuController } from "ionic-angular";
import { HomePage } from "../home/home";
import { RegisterPage } from "../register/register";
import { GlobalProvider } from '../../providers/global/global';
import { Storage } from '@ionic/storage';

@Component({
  selector: 'page-login',
  templateUrl: 'login.html'
})
export class LoginPage implements OnInit {

  username: string;
  password: string;
  constructor(private storage: Storage, public nav: NavController, public forgotCtrl: AlertController, public menu: MenuController, public toastCtrl: ToastController, public global: GlobalProvider) {
    this.menu.swipeEnable(false);
  }
  ngOnInit(): void {
    this.storage.get("username").then(data => {
      if (data !== undefined && data !== null) {
        this.nav.setRoot(HomePage);
      }
    });
  }
  // go to register page
  register() {
    this.nav.setRoot(RegisterPage);
  }

  // login and go to home page
  login() {
    this.global.showLoading(1, "please wait..");
    //https://levyapi.tourismfund.co.ke/api/login/email=rtyui&password=wertyui
    //https://qmsnakuru.kpc.co.ke/apis/login
    //https://qmseldoret.kpc.co.ke/apis/login
    //https://qmskisumu.kpc.co.ke/apis/login
    var prms = "?username=" + this.username + "&password=" + this.password;
    //var prms = "?Email=" + this.username + "&password=" + this.password;
    this.global.post(this.username, this.password, "https://qmskisumu.kpc.co.ke/apis/login" + prms).subscribe(data => {
      var d2 = data as any;
      if (d2.status !== 1) {
        this.storage.set("username", this.username);
        this.nav.setRoot(HomePage);
      } else {
        this.global.post(this.username, this.password, "https://qmseldoret.kpc.co.ke/apis/login" + prms).subscribe(datas => {
          var e2 = datas as any;
          if (e2.status !== 1) {
            this.storage.set("username", this.username);
            this.nav.setRoot(HomePage);
          } else {
            this.global.post(this.username, this.password, "https://qmsnakuru.kpc.co.ke/apis/login" + prms).subscribe(dataw => {
              var f2 = dataw as any;
              if (f2.status !== 1) {
                this.storage.set("username", this.username);
                this.nav.setRoot(HomePage);
              } else {
                this.global.showLoading(0, "");
                this.global.showAlert("NO USER", "We could not match any account in any of our depots");
              }
            });
          }
        });
      }
    });
  }

  forgotPass() {
    let forgot = this.forgotCtrl.create({
      title: 'Forgot Password?',
      message: "Enter you email address to send a reset link password.",
      inputs: [
        {
          name: 'email',
          placeholder: 'Email',
          type: 'email'
        },
      ],
      buttons: [
        {
          text: 'Cancel',
          handler: data => {
            console.log('Cancel clicked');
          }
        },
        {
          text: 'Send',
          handler: data => {
            console.log('Send clicked');
            let toast = this.toastCtrl.create({
              message: 'Email was sended successfully',
              duration: 3000,
              position: 'top',
              cssClass: 'dark-trans',
              closeButtonText: 'OK',
              showCloseButton: true
            });
            toast.present();
          }
        }
      ]
    });
    forgot.present();
  }

}



