import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { AlertController } from 'ionic-angular';
import { LoadingController } from 'ionic-angular';


@Injectable()
export class GlobalProvider {

  constructor(public http: HttpClient, public alert: AlertController, public loading: LoadingController) {
  }

  appHeader = "App-Key";
  appKey = "C742F13F-F981-4835-A9FA-D5A9EC21C3EM";// "C742F13F-F981-4835-A9FA-D5A9EC21C3EF";
  versionKey = "775F6D434E4FEED06E742CB2063D072CE0C46EBC";
  public depot = "kisumu";
  apiBase = "https://qms" + this.depot + ".kpc.co.ke/";
  headers = new HttpHeaders({
    /*"Accept": "application/json"*/
  });
  loader = this.loading.create();
  public student: any;


  fromStore(key: string) {
    return window.localStorage.getItem(key);
  }

  addComma(str: string) {
    return (str + "").replace(/\b(\d+)((\.\d+)*)\b/g,
      function (a, b, c) {
        return (b.charAt(0) > 0 && !(c || ".").lastIndexOf(".") ? b.replace(/(\d)(?=(\d{3})+$)/g, "$1,") : b) +
          c;
      });
  }

  delete(key: string) {
    window.localStorage.removeItem(key);
  }

  requestUrl(method: string) {
    return "https://qms" + this.depot + ".kpc.co.ke/" + method;
  }

  get(method: string, params: any) {
    return this.http.get(this.requestUrl(method), { headers: this.headers, params: params });
  }
  getURL(depot: string): string {
    this.depot = depot;
    var url = "http://qms.kpc.co.ke:9090/";
    if (depot === "eldoret") {
      url = "https://qmseldoret.kpc.co.ke/";
    }
    if (depot === "kisumu") {
      url = "https://qmskisumu.kpc.co.ke/";
    }
    if (depot === "nakuru") {
      url = "https://qmsnakuru.kpc.co.ke/";
    }
    return url;
  }

  post(name, pass, link) {
    let body = new URLSearchParams();
    /*body.set('grant_type', "password");
    body.set('client_id', '4')
    body.set('client_secret', "iyzMdvxWWZrnpWwhJbPMDwb3jlZOQmXXfMfujkNi");
    body.set('username', name)
    body.set('password', pass);*/
    //body.set('scope', "")
    return this.http.post(link, body, { headers: this.headers });
  }
  remember(key: string, value: string) {
    window.localStorage.setItem(key, value);
  }
  put(method: string, params: any) {
    return this.http.put(this.requestUrl(method), params, { headers: this.headers })
  }

  showAlert(title: string, message: string) {
    const appAlert = this.alert.create({
      title: title,
      subTitle: message,
      buttons: ['CLOSE']
    });
    appAlert.present();
  }

  showLoading(mode: Number, content: string) {
    this.loader.setContent(content);
    if (mode === 0) {
      this.loader.dismiss();
      this.loader = this.loading.create();
    } else {
      this.loader.present();
    }
  }

  toggle(elementId: string) {
    var x = document.getElementById(elementId);
    if (x.style.display === "none") {
      x.style.display = "block";
    } else {
      x.style.display = "none";
    }
  }

}



