import { Component, OnInit } from '@angular/core';
import { IonicPage, NavController, NavParams } from 'ionic-angular';
import { GlobalProvider } from '../../providers/global/global';
import { Storage } from '@ionic/storage';
import { ChooseTypePage } from '../choose-type/choose-type';
/**
 * Generated class for the QueueListPage page.
 *
 * See https://ionicframework.com/docs/components/#navigation for more info on
 * Ionic pages and navigation.
 */

@IonicPage()
@Component({
  selector: 'page-queue-list',
  templateUrl: 'queue-list.html',
})
export class QueueListPage implements OnInit {

  ac: any;
  queueList: any;
  qb: any;
  depot: any;
  search: any;
  constructor(private storage: Storage, public navCtrl: NavController, public navParams: NavParams, public global: GlobalProvider) {
  }

  ionViewDidLoad() {

  }
  ngOnInit(): void {
    this.global.showLoading(1, "please wait...");
    this.queueList = [];
    this.qb = [];
    this.ac = this.global.fromStore("ac");
    if (this.ac == null || this.ac == undefined) {
      this.navCtrl.push(ChooseTypePage);
    }
    this.storage.get("depot").then(data => {
      this.depot = data as string;
      this.global.depot = this.depot.toLowerCase();
      this.global.get("handheld/broadqueue/" + this.ac, {}).subscribe(data => {
        var vc = data as any;
        this.queueList = vc.content;
        this.qb = vc.content;
        this.global.showLoading(0, "");
      });
    });
  }

  searchItems() {
    var sp = [];
    if (this.search.length >= 3) {
      for (var qw of this.qb) {
        if (qw.vehicleNumber.toLowerCase().includes(this.search.toLowerCase()) || qw.omc.toLowerCase().includes(this.search.toLowerCase()) || qw.time.date.toLowerCase().includes(this.search.toLowerCase())) {
          sp.push(qw);
        }
      }
      this.queueList = sp;
    } else {
      this.queueList = this.qb;
    }
  }

}



