import { Component, OnInit } from '@angular/core';
import { IonicPage, NavController, NavParams } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { GlobalProvider } from '../../providers/global/global';
import { QueueListPage } from '../queue-list/queue-list';

@IonicPage()
@Component({
  selector: 'page-export-items',
  templateUrl: 'export-items.html',
})
export class ExportItemsPage implements OnInit {
  items: any;

  depot: any;
  constructor(private storage: Storage, public navCtrl: NavController, public navParams: NavParams, public global: GlobalProvider) {
  }
  ngOnInit(): void {
    this.items = [];
    this.global.showLoading(1, "Getting queues");
    this.storage.get("depot").then(data => {
      this.depot = data as string;
      this.global.depot = this.depot.toLowerCase(); + "handheld/broadqueues";
      this.global.get("handheld/broadqueues", {}).subscribe(data => {
        var vc = data as any;
        this.items = vc.content;
        this.global.showLoading(0, "Getting queues");
      });
    });
  }
  localOnly() {
    var sp = [];
    for (var lp of this.items) {
      if (lp.order_type === "Export") {
        sp.push(lp);
      }
    }
    return sp;
  }

  openQueue(id: string) {
    this.global.remember("ac", id);
    this.storage.set("ac", id);
    this.navCtrl.push(QueueListPage);
  }

}



